head.script:
scwin.grdReg_onviewchange = function(info) {
    if (grdReg.getColumnID(info.colIndex) == "PROCESS_MAIN_AGNT_CD") {
        if (info.newValue == "ALL" || info.newValue == "") {
            dc_reg.setCellData(info.rowIndex, "SALES_LV4_MBR_ID", "");
            grdReg.setDisabled("cell", info.rowIndex, "SALES_LV4_MBR_ID", true);
            grdReg.setDisabled("cell", info.rowIndex, "PROMO_EVT_STORE_QTY", true);
        } else {
            grdReg.setDisabled("cell", info.rowIndex, "SALES_LV4_MBR_ID", false);
            grdReg.setDisabled("cell", info.rowIndex, "PROMO_EVT_STORE_QTY", false);
        }
    }
};
scwin.btnInsert_onclick = function(e) {
    var row = 0;
    if (dc_reg.getRowCount() >= 0) {
        row = dc_reg.getRowCount();
    } else {
        row = grdReg.getRealRowIndex(grdReg.getFocusedRowIndex()) + 1;
    }
    dc_reg.insertRow(row);
    dc_reg.setCellData(row, "REGIST_BY", obj.userId);
    dc_reg.setCellData(row, "REGIST_NM", obj.userNm);
    dc_reg.setCellData(row, "STATUS", "C");
    //grdReg.setRowReadOnly(row, false);
    scwin.cellReadOnly(row);
};
scwin.cellReadOnly = function(row) {
    grdReg.setDisabled("cell", row, "PROCESS_MAIN_AGNT_CD", false);
};
scwin.__numRowAdded = function(num) {
    var tr = WebSquare.wUnit.getJq("#grdReg_body_tbody tr").not(".w2grid_hidedRow");
    return tr.length == num;
}
scwin.__selectedVal = function(id, val) {
    return WebSquare.wUnit.getDomById(id).innerText == val;
}
scwin.__triggerDbclick = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.setVal = function() {
    WebSquare.wUnit.getObjById('grdReg_cell_0_1').click();
}
scwin.setVal2 = function() {
    return scwin.__numRowAdded(2) == true;
}
scwin.setVal3 = function() {
    return scwin.__selectedVal('grdReg_cell_0_1', 'KA사업');
}
scwin.setVal4 = function() {
    scwin.__triggerDbclick('grdReg_cell_0_2');
}
scwin.setVal5 = function() {
    return scwin.__selectedVal('grdReg_cell_0_2', 'Hyper/SSM팀');
}
scwin.setVal6 = function() {
    return scwin.__selectedVal('grdReg_cell_0_1', '수도권남부SU');
}
scwin.setVal7 = function() {
    scwin.__triggerDbclick('grdReg_cell_0_2');
}
scwin.setVal8 = function() {
    return scwin.__selectedVal('grdReg_cell_0_2', '강서SO');
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 브라우저에서 행추가 버튼을 두번 클릭한다.
    //1. Double-click the Add Row button in the browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btnInsert').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btnInsert').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1. 그리드에 행이 2개 추가된다.
    //1. Two rows are added to the grid.
    WebSquare.wUnit.addCommand("assert", "scwin.setVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 처리주체 컬럼에서 KA사업 을 선택한다.
    //2. Select the KA business in the Processing Principal column.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grdReg___selectbox_PROCESS_MAIN_AGNT_CD_itemTable_2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. 처리주체 컬럼에 KA사업 이 선택된다.
    //2. The KA business is selected in the processing subject column.
    WebSquare.wUnit.addCommand("assert", "scwin.setVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 3. SO/KA 컬럼에서 임의의 데이터를 체크한 후 빈공간을 클릭해서 포커스 아웃시킨다.
    //3. Check any data in the SO / KA column and click on the empty space to focus it out.
    WebSquare.wUnit.addCommand("set", "scwin.setVal4()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grdReg___checkcombobox_SALES_LV4_MBR_ID_itemTable_0_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grdReg___checkcombobox_SALES_LV4_MBR_ID_button').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 3. SO/KA 컬럼에 데이터가 선택된다.
    //3. Data is selected in the SO / KA column.
    WebSquare.wUnit.addCommand("assert", "scwin.setVal5()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 4. 처리주체 컬럼에서 수도권남부SU 를 선택한다.
    //4. Select the southern SU of the metropolitan area from the treatment subject column.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grdReg_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grdReg___selectbox_PROCESS_MAIN_AGNT_CD_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 4. 수도권남부SU 가 선택한다.
    //4. Southern SU of the metropolitan area chooses.
    WebSquare.wUnit.addCommand("assert", "scwin.setVal6()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 5. SO/KA 컬럼에서 임의의 데이터를 체크한 후 빈공간을 클릭해서 포커스 아웃시킨다.
    //5. Check any data in the SO / KA column and click on empty space to focus out.
    WebSquare.wUnit.addCommand("set", "scwin.setVal7()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grdReg___checkcombobox_SALES_LV4_MBR_ID_itemTable_1_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grdReg___checkcombobox_SALES_LV4_MBR_ID_button').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 5. SO/KA 컬럼에 데이터가 선택된다.
    //5. Data is selected in the SO / KA column.
    WebSquare.wUnit.addCommand("assert", "scwin.setVal8()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
